input.command:
cat /etc/redwood-release; cd /app/workspace && python3 - <<'EOF'
import json,hashlib,os
m=json.load(open('index/manifest.json'))
old=m['source_sha1']; root='/app/R/sources'
new={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        p=os.path.join(dp,f); rel=os.path.relpath(p,root)
        new[rel]=hashlib.sha1(open(p).read().encode()).hexdigest()
added=sorted(set(new)-set(old)); changed=sorted(k for k in old if k in new and old[k]!=new[k]); gone=sorted(set(old)-set(new))
print(len(old),len(new),'added',len(added),'changed',len(changed),'gone',len(gone))
json.dump({'added':added,'changed':changed},open('/tmp/r1diff.json','w'))
for a in added: print('A',a, os.path.getsize(os.path.join(root,a)))
for c in changed: print('C',c, os.path.getsize(os.path.join(root,c)))
EOF
ls -la /app/R; ls -la --time-style=+%F /app/R/*.md /app/R/*.txt /app/R/*.yaml

cd /app/R/sources; python3 -c "
import json; d=json.load(open('/tmp/r1diff.json')); print(d['changed'])
import collections; print(collections.Counter('/'.join(a.split('/')[:2]) for a in d['added']).most_common(60))
"

